#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define TIMEOUT_MS 200

static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static struct k_thread tdata;
static K_THREAD_STACK_DEFINE(tstack2, STACK_SIZE);
static struct k_thread tdata2;


static K_EVENT_DEFINE(test_event);

/* Helper thread that waits for something to be posted to an event,
 * then records the value and the time it was received.
 */
static void drive_receive_events(void *p1, void *p2, void *p3)
{
	uint32_t evt_mask = (uint32_t)POINTER_TO_UINT(p1);
	uint32_t *evt_received = p2;
	int64_t *uptime_received = p3;
	bool wait_for_all = (bool)POINTER_TO_UINT(p3);

	*evt_received = k_event_wait(&test_event, evt_mask, wait_for_all, K_FOREVER);
	if (uptime_received != NULL) {
		*uptime_received = k_uptime_get();
	}
}

/**
 * @brief Test that posting an event wakes a thread waiting for it.
 *
 * The helper thread is started and waits on an event.  The main
 * thread sleeps to allow the helper to run and block, then posts
 * the event and verifies that the thread received it.
 *
 * @ingroup kernel_event_tests
 *
 * @see k_event_post(), k_event_wait()
 */
ZTEST(events_api, test_event_post)
{
	uint32_t events_to_send = 0x101;
	uint32_t events_received = 0;
	int64_t uptime_received = 0;

	k_event_init(&test_event);

	k_thread_create(&tdata, tstack, K_THREAD_STACK_SIZEOF(tstack),
			drive_receive_events,
			UINT_TO_POINTER(events_to_send), &events_received, &uptime_received,
			K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	/* Let the other thread run and wait on the event */
	k_msleep(100);

	int64_t uptime_before_send = k_uptime_get();

	k_event_post(&test_event, events_to_send);

	k_thread_join(&tdata, K_FOREVER);

	zassert_equal(events_received, events_to_send,
		      "did not receive sent events");
	zassert_true(uptime_received >= uptime_before_send,
		     "received event before it was sent");
}

/**
 * @brief Test that waiting for an event that has already been posted
 * completes immediately.
 *
 * An event is posted.  Then a helper thread is started that waits on
 * that event.  The helper should not block.
 *
 * @ingroup kernel_event_tests
 *
 * @see k_event_post(), k_event_wait()
 */
ZTEST(events_api, test_event_receive_existing)
{
	uint32_t events_to_send = 0x202;
	uint32_t events_received = 0;
	int64_t uptime_received = 0;

	k_event_init(&test_event);

	k_event_post(&test_event, events_to_send);

	int64_t uptime_before_wait = k_uptime_get();

	k_thread_create(&tdata, tstack, K_THREAD_STACK_SIZEOF(tstack),
			drive_receive_events,
			UINT_TO_POINTER(events_to_send), &events_received, &uptime_received,
			K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	k_thread_join(&tdata, K_FOREVER);

	zassert_equal(events_received, events_to_send,
		      "did not receive sent events");

	/* Technically the other thread could be scheduled after the
	 * tick in which we posted, but it's not going to be delayed
	 * long.
	 */
	zassert_true(uptime_received <= uptime_before_wait + 1,
		     "wait for existing event was delayed");
}

ZTEST(events_api, test_event_set_and_clear)
{
	k_event_init(&test_event);
	zassert_equal(test_event.events, 0, "event not initialized to 0");

	k_event_set(&test_event, 0x1234);
	zassert_equal(test_event.events, 0x1234, "event_set failed");

	k_event_clear(&test_event, 0x1030);
	zassert_equal(test_event.events, 0x0204, "event_clear failed");
}

ZTEST(events_api, test_event_test)
{
	uint32_t events;

	k_event_init(&test_event);
	k_event_post(&test_event, 0xABCD);

	events = k_event_test(&test_event, 0x1234);
	zassert_equal(events, 0x200, "k_event_test failed");
}

static void drive_timeout(void *p1, void *p2, void *p3)
{
	uint32_t *events_received = p1;
	*events_received = k_event_wait(&test_event, 0x1, false, K_MSEC(TIMEOUT_MS));
}

ZTEST(events_api, test_event_timeout)
{
	uint32_t events_received = 0xAAAA;

	k_event_init(&test_event);

	k_thread_create(&tdata, tstack, K_THREAD_STACK_SIZEOF(tstack),
			drive_timeout, &events_received, NULL, NULL,
			K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	k_thread_join(&tdata, K_FOREVER);

	zassert_equal(events_received, 0, "wait should have timed out and returned 0");
}

static void waiter_thread(void *p1, void *p2, void *p3)
{
	uint32_t expected_events = POINTER_TO_UINT(p1);
	uint32_t received_events;

	received_events = k_event_wait(&test_event, 0xFFFFFFFF, true, K_FOREVER);
	zassert_equal(received_events, expected_events, "waiter received wrong events");
}

ZTEST(events_api, test_multiple_waiters)
{
	k_event_init(&test_event);

	k_thread_create(&tdata, tstack, K_THREAD_STACK_SIZEOF(tstack),
			waiter_thread, UINT_TO_POINTER(0x1), NULL, NULL,
			K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	k_thread_create(&tdata2, tstack2, K_THREAD_STACK_SIZEOF(tstack2),
			waiter_thread, UINT_TO_POINTER(0x2), NULL, NULL,
			K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	k_msleep(100); /* let waiters block */

	k_event_post(&test_event, 0x1 | 0x2);

	k_thread_join(&tdata, K_FOREVER);
	k_thread_join(&tdata2, K_FOREVER);
}

/**
 * @brief Test that waiting for an event with reset leaves the event object
 * in the expected state.
 *
 * A helper thread is started and waits on an event using k_poll with
 * the K_POLL_STATE_EVENT_RESET flag.  The main thread posts the
 * event.  The helper thread verifies that the event object's event
 * state has been cleared.
 *
 * The helper thread then posts a different event and waits on it
 * without the reset flag, and verifies that the event object's event
 * state is not cleared.
 *
 * @ingroup kernel_event_tests
 *
 * @see k_poll(), K_POLL_STATE_EVENT_RESET
 */
static void drive_reset_on_wait(void *p1, void *p2, void *p3)
{
	struct k_poll_event events[1] = {
		K_POLL_EVENT_INITIALIZER(K_POLL_TYPE_EVENT,
					 K_POLL_MODE_NOTIFY_ONLY,
					 &test_event),
	};
	events[0].events = 0xFFF;

	/* test: wait for event, with reset */
	events[0].state |= K_POLL_STATE_EVENT_RESET;
	TC_PRINT("Waiting for event 0x456, with reset\n");
	(void)k_poll(events, 1, K_FOREVER);
	zassert_equal(events[0].events, 0x456, "did not receive expected events");
	zassert_equal(test_event.events, 0, "events were not reset");

	/* test: wait for event, no reset */
	k_event_post(&test_event, 0x123);
	events[0].state = K_POLL_STATE_NOT_READY;
	TC_PRINT("Waiting for event 0x123, no reset\n");
	(void)k_poll(events, 1, K_FOREVER);
	zassert_equal(events[0].events, 0x123, "did not receive expected events");
	zassert_equal(test_event.events, 0x123, "events were reset");
}

ZTEST(events_api, test_event_reset_on_wait)
{
	k_event_init(&test_event);

	k_thread_create(&tdata, tstack, K_THREAD_STACK_SIZEOF(tstack),
			drive_reset_on_wait, NULL, NULL, NULL,
			K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	/* Allow waiter to run and block */
	k_msleep(100);

	k_event_post(&test_event, 0x456);

	k_thread_join(&tdata, K_FOREVER);
}

ZTEST_SUITE(events_api, NULL, NULL, NULL, NULL, NULL);
